import{_ as t,c as o,o as c,a5 as r}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"Count RPC 服务","description":"","frontmatter":{"title":"Count RPC 服务","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#5","branch":"main","level":0,"order":5},"headers":[],"relativePath":"posts/projects/zfeed/05-count-rpc-service/index.md","filePath":"posts/projects/zfeed/05-count-rpc-service/index.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/05-count-rpc-service/index.md"};function n(l,e,i,p,d,u){return c(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="count-rpc-服务" tabindex="-1">Count RPC 服务 <a class="header-anchor" href="#count-rpc-服务" aria-label="Permalink to &quot;Count RPC 服务&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/count.go" target="_blank" rel="noreferrer">app/rpc/count/count.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/count/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/batchgetcountlogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/batchgetcountlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/count_cache_helper.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/count_cache_helper.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getuserprofilecountslogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getuserprofilecountslogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/inclogic.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/inclogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/read_path_test.go" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/read_path_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/svc/servicecontext.go" target="_blank" rel="noreferrer">app/rpc/count/internal/svc/servicecontext.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/go.mod" target="_blank" rel="noreferrer">go.mod</a></li></ul></details><p>Count RPC 服务是一个专门的高性能计数系统，负责管理 <code>zfeed</code> 平台上的各类数值指标。它追踪点赞、评论、收藏、粉丝数和关注数等高频事件。</p><p>该服务通过事件驱动架构将计数递增与主互动流程解耦，确保社交功能的高写入负载不会影响核心系统可用性。</p><h2 id="系统角色与范围" tabindex="-1">系统角色与范围 <a class="header-anchor" href="#系统角色与范围" aria-label="Permalink to &quot;系统角色与范围&quot;">​</a></h2><p><code>count-rpc</code> 服务充当所有聚合计数的事实来源。它提供用于读取计数的 gRPC 接口，并通过 Canal 消费数据库变更事件，异步更新这些计数。</p><h3 id="关键职责" tabindex="-1">关键职责 <a class="header-anchor" href="#关键职责" aria-label="Permalink to &quot;关键职责&quot;">​</a></h3><ul><li>异步更新：通过 MySQL binlog 事件处理计数递增和递减，在不阻塞用户请求的前提下保证最终一致性。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/count.go#L49-L51" target="_blank" rel="noreferrer">app/rpc/count/count.go#49-51</a></li><li>统一存储：将所有计数类型存储在通用表结构（<code>zfeed_count_value</code>）中，并通过 <code>biz_type</code> 和 <code>target_type</code> 分类。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L5-L15" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#5-15</a></li><li>高性能读取：实现基于 Redis 缓存和分布式锁的多层读取策略，防止缓存击穿。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L43-L54" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#43-54</a></li><li>幂等性：使用去重表（<code>zfeed_mq_consume_dedup</code>）确保 Kafka 重投递消息不会导致重复计数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L21-L26" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#21-26</a></li></ul><h2 id="服务架构" tabindex="-1">服务架构 <a class="header-anchor" href="#服务架构" aria-label="Permalink to &quot;服务架构&quot;">​</a></h2><p>该服务分为两条主要执行路径：写链路（事件驱动）和读链路（请求-响应）。</p><h3 id="实体映射图" tabindex="-1">实体映射图 <a class="header-anchor" href="#实体映射图" aria-label="Permalink to &quot;实体映射图&quot;">​</a></h3><p>该图将高层系统组件映射到服务中定义的具体代码实体和数据库表。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/server/counterserviceserver.go" target="_blank" rel="noreferrer">app/rpc/count/internal/server/counterserviceserver.go</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L5-L30" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#5-30</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/inclogic.go#L21-L28" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/inclogic.go#21-28</a></p><h2 id="子系统与子页面" tabindex="-1">子系统与子页面 <a class="header-anchor" href="#子系统与子页面" aria-label="Permalink to &quot;子系统与子页面&quot;">​</a></h2><h3 id="_1-count-写链路与事件分发" tabindex="-1">1. Count 写链路与事件分发 <a class="header-anchor" href="#_1-count-写链路与事件分发" aria-label="Permalink to &quot;1. Count 写链路与事件分发&quot;">​</a></h3><p>写路径主要由 Canal Consumer 驱动。当用户执行动作（例如点赞内容）时，变更会记录到 <code>interaction-rpc</code> 数据库中。Canal 捕获该 binlog 事件并发布到 Kafka。<code>count-rpc</code> 服务消费这些事件，再通过 <code>Dispatcher</code> 路由到具体更新策略。</p><ul><li>乐观锁：更新 <code>zfeed_count_value</code> 时使用 <code>version</code> 字段，防止并发递增时丢失更新。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L11-L11" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#11</a></li><li>原子 delta：<code>CountOperator</code> 会根据事件类型应用正向或负向 delta。</li></ul><p>详情请参阅<a href="./01-count-write-chain-and-event-dispatch.html">Count 写链路与事件分发</a>。</p><h3 id="_2-count-读链路与缓存失效" tabindex="-1">2. Count 读链路与缓存失效 <a class="header-anchor" href="#_2-count-读链路与缓存失效" aria-label="Permalink to &quot;2. Count 读链路与缓存失效&quot;">​</a></h3><p>读路径面向内容 Feed 和用户资料等高流量场景优化。它支持批量查询，以降低渲染内容列表时的 gRPC 开销。</p><ul><li>缓存策略：使用 Redis 和 Cache-Aside 模式。发生缓存未命中时，通过 <code>redislock.NewRedisLock</code> 获取分布式锁，确保只有一个请求从 MySQL 重建缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L75-L80" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#75-80</a></li><li>延迟失效：为保证写入后的一致性，服务使用 <code>DelayedCacheInvalidator</code> 在短暂延迟后清理 Redis key，确保数据库副本已追上更新。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/svc/servicecontext.go#L23-L24" target="_blank" rel="noreferrer">app/rpc/count/internal/svc/servicecontext.go#23-24</a></li></ul><p>详情请参阅<a href="./02-count-read-chain-and-cache-invalidation.html">Count 读链路与缓存失效</a>。</p><h2 id="数据结构概览" tabindex="-1">数据结构概览 <a class="header-anchor" href="#数据结构概览" aria-label="Permalink to &quot;数据结构概览&quot;">​</a></h2><p>服务使用高度规范化的结构，在一张表中处理多种业务指标（点赞、关注等）。</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>biz_type</code></td><td><code>int32</code></td><td>计数类别，例如 <code>LIKE</code>、<code>COMMENT</code>、<code>FOLLOW</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L7-L7" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#7</a></td></tr><tr><td><code>target_type</code></td><td><code>int32</code></td><td>被计数实体的类型，例如 <code>CONTENT</code>、<code>USER</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L8-L8" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#8</a></td></tr><tr><td><code>target_id</code></td><td><code>int64</code></td><td>内容或用户的 ID。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L9-L9" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#9</a></td></tr><tr><td><code>value</code></td><td><code>int64</code></td><td>当前聚合计数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L10-L10" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#10</a></td></tr><tr><td><code>owner_id</code></td><td><code>int64</code></td><td>用于聚合用户资料统计，例如收到的总点赞数。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/model/count_model.go#L12-L12" target="_blank" rel="noreferrer">app/rpc/count/internal/model/count_model.go#12</a></td></tr></tbody></table><h3 id="集成示例-内容详情" tabindex="-1">集成示例：内容详情 <a class="header-anchor" href="#集成示例-内容详情" aria-label="Permalink to &quot;集成示例：内容详情&quot;">​</a></h3><p>当 <code>content-rpc</code> 为 <code>GetContentDetail</code> 组装响应时，会并发调用 <code>count-rpc</code> 获取互动指标。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/content/internal/logic/content/getcontentdetaillogic.go#L193-L196" target="_blank" rel="noreferrer">app/rpc/content/internal/logic/content/getcontentdetaillogic.go#193-196</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/logic/getcountlogic.go#L35-L54" target="_blank" rel="noreferrer">app/rpc/count/internal/logic/getcountlogic.go#35-54</a></p>',28)])])}const h=t(a,[["render",n]]);export{b as __pageData,h as default};
